import React from "react";
import { useState, useEffect, useRef } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-toastify";
import Select from "react-select";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import { useSearchParams, useNavigate } from "react-router-dom";
import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";
import { GetLedgerList } from "../dataservice/getLedgerList";
import apiAcc from "../../components/api/AccWebcall";
import api from "../../components/api/Webcall";
import appsettings from "../../appsettings.json"
const apiendpoints = appsettings.ApiEndpoints;

function AccountHeads() {

    const navigate = useNavigate();
    const { register, getValues, setValue, reset } = useForm();
    const [searchParams, setSearchParams] = useSearchParams();

    let qDet = useRef(JSON.parse(decompressBase64(atob(searchParams.get("_q")))));

    let addoredit = useRef("Add");

    let norPP = useRef(10);
    const [norSkip, setNorSkip] = useState(0);

    const [ledgers, setLedgers] = useState(null);
    const [currencies, setCurrencies] = useState([]);
    const [lggroups, setLgGroups] = useState([]);

    const [currencyid, setCurrencyId] = useState(0);
    const [groupid, setGroupId] = useState(0);

    const [isLedgerNameDisabled, setLedgerNameDisabled] = useState(false);
    const [isCurrencyDisabled, setCurrencyDisabled] = useState(false);

    const [showModal, setShowModal] = useState(false);
    const modelHandleHide = () => setShowModal(false);


    const fetctLedgers = async (skip, nrp) => {
        let frmData = {};
        frmData["skip"] = skip;
        frmData["top"] = nrp;
        const res = await GetLedgerList(frmData);
        if (res) {
            if (res.hdr) {
                if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                    if (res.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    if (res.body) {

                        if (res.body.ledgers) {
                            setLedgers(res.body.ledgers);
                        }

                        if (res.body.currency) {
                            let currency = res.body.currency;
                            const curr = [];
                            currency.map((data, i) => { curr.push({ value: data.currid, label: data.currcode }) });
                            setCurrencies(curr);
                        }

                        if (res.body.lggroup) {
                            let lggroup = res.body.lggroup;
                            const grup = [];
                            lggroup.map((data, i) => { grup.push({ value: data.grid, label: data.grna }) });
                            setLgGroups(grup);
                        }
                    }
                }
            }
        }
    }

    const onClick_FirstPage = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = 0;
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);  
    }

    const onClick_LastPage = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = 0;
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);  
    }

    const onClick_RightArrow = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = norSkip + rPP;
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);
    }

    const onClick_LeftArrow = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = norSkip - rPP;
        if (no<=0){ no = 0;}
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);
    }

    const onChange_cmbRowPP = (e) => {
        fetctLedgers(norSkip, e.target.value);
    }

    const onChange_cmbCurrency = (obj) => {
        setCurrencyId(obj.value);
    }

    const onChange_cmbGroup = (obj) => {
        setGroupId(obj.value);
    }

    const addNewLedger = () => {
        reset({ txtLedgerId: 0, txtLedgerName: null, cbBudget: false, cbCost: false });
        setCurrencyId(null);
        setGroupId(null);
        setLedgerNameDisabled(false);
        setCurrencyDisabled(false);
        setShowModal(true);
    }

    const editLedger = (lgid) => {
        let ledg = ledgers.find(x => x.lgid == lgid);
        reset({ txtLedgerId: lgid, txtLedgerName: ledg.lgna, cbBudget: ledg.ib, cbCost: ledg.ic });
        setCurrencyId(ledg.currid);
        setGroupId(ledg.gid);
        setLedgerNameDisabled(true);
        setCurrencyDisabled(true);
        setShowModal(true);
    }

    const saveLedger = (e) => {

        console.clear();

        let frmData = {};

        frmData["txtLedgerId"] = getValues("txtLedgerId");
        frmData["txtLedgerName"] = getValues("txtLedgerName");
        frmData["cmbCurrencyId"] = currencyid;
        frmData["cmbGroupId"] = groupid;
        frmData["cbIsBudget"] = getValues("cbBudget");
        frmData["cbIsCost"] = getValues("cbCost");

        frmData["txtBrLedgMap"] = [];
        frmData["txtLedgCurrMap"] = [];

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Save Ledger", orgid: "", vendid: "_Acc" };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};
        apiAcc.post(apiendpoints.UpdLedger, compressBase64(data), reqHdr)
            .then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));
                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {

                            e.target.disabled = false;

                            if (res.fdr) {
                                setTimeout(() => {

                                    let strMsg = "";
                                    res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                    toast.error(strMsg);

                                }, 300);
                            }
                        }
                        else {

                            fetctLedgers();
                            setShowModal(false);

                        }
                    }
                }
            });
    }


    /*  Use Effect */
    useEffect(() => {
        fetctLedgers(norSkip, norPP.current);
    }, []);


    return (

        <>

            <div className="row pad-top-0-5em pad-left-15 pad-right-15">

                <div className="card-header">

                    <strong className="card-title">Account Heads</strong>

                    <div className=" float-end">
                        <button className="btn-link btn-bg"><i class="bi bi-chevron-bar-left" onClick={()=>{ onClick_FirstPage(); } }></i></button>
                        <button className="btn-link btn-bg"><i class="bi bi-caret-left" onClick={()=>{ onClick_LeftArrow(); }}></i></button>
                        <select {...register("cmbRowPP")} style={{ fontSize: "10pt" }} onChange={(e) => { onChange_cmbRowPP(e); }}>
                            <option value="10">10</option>
                            <option value="25">25</option>
                            <option value="50">50</option>
                            <option value="100">100</option>
                        </select>
                        <button className="btn-link btn-bg"><i class="bi bi-caret-right" onClick={()=>{ onClick_RightArrow(); }}></i></button>
                        <button className="btn-link btn-bg"><i class="bi bi-chevron-bar-right" onClick={()=>{ onClick_LastPage(); }}></i></button>
                        <button onClick={() => { addNewLedger(); }} className="btn-link">+ Add New</button>
                    </div>

                </div>

            </div>

            <div className="row pad-top-0-5em pad-left-15 pad-right-15">

                <table className="lst-grid">
                    <thead>
                        <tr>
                            <th>Id</th>
                            <th>Account Head</th>
                            <th>Currency</th>
                            <th>Group</th>
                            <th>Budget</th>
                            <th>Cost</th>
                            <th>Manage</th>
                        </tr>
                    </thead>
                    <tbody>

                        {(ledgers !== null) ?
                            ledgers.map((data, i) => {
                                return (
                                    <tr className="ledger-row">
                                        <td>{data["lgid"]}</td>
                                        <td>{data["lgna"]}</td>
                                        <td align="center">{data["curr"]}</td>
                                        <td>{data["gna"]}</td>
                                        <td align="center">{data["ib"] === 1 ? "Yes" : "No"}</td>
                                        <td align="center">{data["ic"] === 1 ? "Yes" : "No"}</td>
                                        <td> <button type="button" className="btn-link" onClick={() => { editLedger(data["lgid"]) }}>edit</button> </td>
                                    </tr>
                                )
                            })
                            : <tr> <td colSpan={7}> Loading... </td> </tr>
                        }

                    </tbody>
                </table>

            </div>


            <Modal show={showModal} onHide={modelHandleHide} size="xl"
                aria-labelledby="contained-modal-title-vcenter" centered >

                <Modal.Header>
                    <Modal.Title>{addoredit.current} Account Head</Modal.Title>
                    <div className="float-end">
                        <label>Id :&nbsp;</label>
                        <input type="text" {...register("txtLedgerId")} disabled="true" />
                    </div>
                </Modal.Header>

                <Modal.Body>

                    <div className="row">

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-8">
                                <label htmlFor="txtLedgerName" className="form-label">Head Name</label>
                                <input type="text" className="form-control" {...register("txtLedgerName")} disabled={isLedgerNameDisabled} />
                            </div>

                            <div className="col-md-4">
                                <label htmlFor="cmbCurrencyId" className="form-label">Currency</label>
                                <Select {...register("cmbCurrencyId")} options={currencies} isDisabled={isCurrencyDisabled}
                                    value={currencies.find(x => x.value === currencyid)}
                                    onChange={(e) => { onChange_cmbCurrency(e); }} > </Select>
                            </div>

                        </div>

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-8">
                                <label htmlFor="cmbGroup" className="form-label">Head Group</label>
                                <Select {...register("cmbGroup")} options={lggroups}
                                    value={lggroups.find(x => x.value === groupid)}
                                    onChange={e => { onChange_cmbGroup(e); }} > </Select>
                            </div>

                            <div className="col-md-2 mar-top-2em">
                                <input type="checkbox" {...register("cbBudget")} />
                                {" "}<label htmlFor="cbBudget" className="form-label">Budget</label>
                            </div>

                            <div className="col-md-2 mar-top-2em">
                                <input type="checkbox" {...register("cbCost")} />
                                {" "}<label htmlFor="cbCost" className="form-label">Costing</label>
                            </div>

                        </div>

                    </div>

                </Modal.Body>

                <Modal.Footer>
                    <Button variant="secondary" onClick={(e) => { saveLedger(e); e.target.disabled = true; }} >Save</Button>
                    <Button variant="secondary" onClick={() => { setShowModal(false); }}>Cancel</Button>
                </Modal.Footer>

            </Modal>

        </>
    );
}

export default AccountHeads;
