import axios from "axios";

const BASE_URL = process.env.REACT_APP_FinXAccUrl;

const apiAcc = axios.create({
  baseURL: BASE_URL,
  withCredentials: true
});

// let setLoading;
// export function initializeLoadingSetter(setter) {
//   setLoading = setter;
// }

apiAcc.interceptors.response.use(
  (response) => {

    return response;
  },

  (error) => {
    if (error.response.status === 401) {
      debugger;
      return error.response;
    }
    return Promise.reject(error);
  }
);

export function PostCallHeader(url, data, header) {
  const respdata = axios.post(url, data, header);
  return respdata;
}

export default apiAcc;